import type { DesignToolPanelId } from "./designCommands";
export interface EditorGuideEntry { id: string; title: string; category: "canvas" | "layers" | "data" | "pages" | "timeline"; web: string; mobile: string; shortcut?: string; panel?: DesignToolPanelId }
export const EDITOR_GUIDE: readonly EditorGuideEntry[] = [
  { id: "chart-category-axis", title: "Space and angle chart category labels", category: "data", web: "In Axes and scale, choose a label cadence from one to ten categories while retaining every plotted row. The first and last categories remain labelled. Vertical category charts can angle their labels from minus ninety to ninety degrees.", mobile: "Angled labels use a single line and reserve extra space below the plot. Return to zero degrees for wrapped labels. Label cadence and angle are retained by local draft undo, chart styles and vector SVG export.", panel: "data" },
  { id: "chart-scale-intervals", title: "Choose chart grid and label intervals", category: "data", web: "Axes and scale can divide the value axis into one to twenty intervals. Radar charts use the same control for grid rings. Scatter and bubble charts can independently divide their horizontal axis, including calendar-date axes.", mobile: "Intervals change grid and scale-label density without modifying the source values or numeric bounds. Four intervals preserve the previous default. Saved chart styles, draft undo and standalone graphic SVG output retain the chosen density.", panel: "data" },
  { id: "chart-row-filters", title: "Filter displayed chart rows without deleting data", category: "data", web: "Rows to display can combine up to three label conditions, numeric ranges or source-row ranges. Match labels by contains, equals, excludes, starts or ends, with optional case matching. Numeric ranges can use the first series, a named series or the total across series. All active conditions must match.", mobile: "Disable, edit or remove filters while retaining every source row. The displayed chart and graphic exports show matching rows; Export displayed rows copies or downloads that subset. Histogram bin-count exports follow the filtered observations. Category colours and series values kept aligned. Missing named-series filters are ignored and reported in the editor. Progress charts and filled-icon progress graphics retain their first-value workflow.", panel: "data" },
  { id: "area-chart-layouts", title: "Use stacked, proportional and streamgraph areas", category: "data", web: "Area chart Design includes overlapping, stacked, proportional and centred streamgraph layouts. Use multiple series to create cumulative bands or 100-percent shares. Streamgraphs centre each category total around zero; the reference target is retained in the source but hidden in that layout.", mobile: "Stacked, proportional and streamgraph layouts require nonnegative values. Original counts remain in the data when shares are shown. Line shapes, marker patterns, palettes, legends and label wrapping work across these layouts. Three starters demonstrate stacked growth, changing shares and centred listening trends.", panel: "data" },
  { id: "chart-date-axis", title: "Plot observations against calendar dates", category: "data", web: "Scatter and bubble charts can use Dates and UTC times as their horizontal data type in Axes and scale. Enter ISO dates such as 2026-01-31, or UTC timestamps such as 2026-01-31T14:30Z. Spacing follows elapsed time, including gaps. Choose date, month, year, time or combined labels and a supported locale.", mobile: "Date bounds extend the automatic scale and keep all observations visible. Sorting by X and spreadsheet import mapping understand date mode. Source labels stay as ISO text; numeric X number formats remain available in number mode. UTC interpretation is consistent across devices, and an irregular-date starter is included.", panel: "data" },
  { id: "graphic-text-direction", title: "Mix left-to-right and right-to-left graphic labels", category: "data", web: "Chart and table labels resolve their text direction independently. Arabic or Hebrew labels can share a graphic with Latin labels, numeric ticks and series names. Physical left, centre and right alignment follows the chosen chart or table layout.", mobile: "Direction handling is shared by native canvas and standalone graphic SVG output, including chart titles, captions, legends and table cells. Choose a graphic font that contains the characters used in your labels.", panel: "data" },
  { id: "chart-marks", title: "Distinguish chart series with shapes and patterns", category: "data", web: "In chart Design, choose circle, square, diamond, triangle or cross point shapes and solid, dashed, dotted or dash-and-dot lines. Multiple series can cycle shapes and patterns automatically. Legend keys follow the same appearance, including SVG downloads.", mobile: "Marker controls apply to line, area, scatter, dot and lollipop plots. Radar charts support line patterns. Set point size to zero to hide markers. Bubble charts keep circular marks so their areas still represent size. These settings travel with saved chart styles and draft undo.", panel: "data" },
  { id: "chart-category-summary", title: "Combine repeated chart categories", category: "data", web: "In a categorical chart, open Combine repeated categories and choose Sum, Average, Row count, Minimum or Maximum. Optional space and case matching determines which labels belong together. Inspect the resulting category count, then replace the draft with the summary.", mobile: "Each series is summarized separately and categories retain their first label, order and category colour. Row count gives every series the number of matching rows. Scatter, bubble, histogram and progress charts retain their own data workflows. Undo draft change restores the original data and colours.", panel: "data" },
  { id: "graphic-draft-history", title: "Undo chart and table draft changes", category: "data", web: "Use Undo draft change and Redo draft change above the graphic preview to move through local draft edits. History includes source data, chart type, colours, appearance, table cell formatting, merges and manual row or column sizes. It also includes switching between chart and table drafts.", mobile: "Draft history is scoped to the current selection and resets when the selected graphic is loaded or updated. Up to eighty bounded snapshots are retained while the panel stays open. Applying the graphic remains one document edit in the main undo history; unapplied drafts are not persisted by these controls.", panel: "data" },
  { id: "data-cell-editor", title: "Navigate and edit spreadsheet cells", category: "data", web: "The data grid highlights its active cell. Go to an existing address such as D12, or use Previous cell and Next cell to move through rows. The whole-cell editor supports text and line breaks up to two hundred characters without squeezing content into a grid column. This edits the current draft; update the graphic to apply it.", mobile: "The same cell controls work in the compact grid and expanded data editor. Navigating pages scrolls the target column into view. Table typography and merged-cell settings remain attached to grid positions. Formula-looking values remain plain text and are not evaluated.", panel: "data" },
  { id: "bulk-connection-files", title: "Transfer a bulk connection setup", category: "pages", web: "Export the current bulk connections to a small JSON setup file, then import it in another design or device. Setups connect named text, QR, image and link layers, plus page names, notes and sections. Spreadsheet records and artwork are not included.", mobile: "Name connected layers uniquely before exporting. On import, inspect the matched, missing and ambiguous counts. Apply matching connections to replace their mappings while keeping unrelated connections. Ambiguous names and missing columns or layers are skipped, and generating pages stays a separate action.", panel: "bulk" },
  { id: "bulk-name-connections", title: "Connect matching template layer names", category: "pages", web: "Bulk create can propose text and QR connections when complete layer names match spreadsheet headings. Optionally include photo frames or match complete text content. Inspect the proposed connections and apply them together.", mobile: "Matching ignores case, repeated spaces, hyphens and underscores. Existing valid connections and text placeholders are retained. Ambiguous column or label matches are skipped. Photo connections use the same named-photo lookup and record validation as manual connections.", panel: "bulk" },
  { id: "bulk-placeholder-format", title: "Format spreadsheet placeholders", category: "pages", web: "Bulk create’s placeholder builder can trim spaces, change text case, format numbers, percentage points and currencies, and add blank-value fallbacks, prefixes or suffixes. Copy the generated placeholder into template text or QR content, then use the layer’s placeholder connection. The selected record previews the formatted value.", mobile: "Numeric formatting supports catalogue locales and currencies with zero to four decimals. Numeric source values must be plain finite numbers within one trillion; 25 stays 25 percent in percentage mode. Formatting leaves the spreadsheet unchanged and also works in placeholder-based page names or notes. Invalid formatting is reported before page generation commits.", panel: "bulk" },
  { id: "bulk-populated-preview", title: "Preview a populated bulk page", category: "pages", web: "Choose a preview data row in Bulk create, then expand Preview populated page. It renders the template with that record’s connected text, QR content, layer links and named source photos. Editing data, connections or the template refreshes the optional preview.", mobile: "Previewing creates a temporary page snapshot without committing it to the design. It previews the selected record even when the batch filter excludes that record. Missing named photos and invalid QR or link content are reported with the record. Generate pages remains the separate action that changes the document.", panel: "bulk" },
  { id: "bulk-import-mapping", title: "Choose spreadsheet records for bulk pages", category: "pages", web: "Bulk create can import files or pasted spreadsheet cells through the mapping draft. Choose automatic or explicit separators, up to twenty source columns and a window of up to fifty data records. Column headings come from the first file row and must be unique. Preview the selected cells before replacing the bulk data draft.", mobile: "The bounded reader accepts up to one thousand records plus headings and one hundred columns. Leading zeros and other cell text stay unchanged. Using selected data resets the record range and filter while retaining compatible column connections. Page generation remains a separate document edit.", panel: "bulk" },
  { id: "mapped-data-import", title: "Choose spreadsheet columns and rows before import", category: "data", web: "Import CSV or TSV, or paste spreadsheet cells to open a mapping draft. Inspect the first file rows and the mapped selection, choose automatic or explicit comma, tab or semicolon separators, heading handling, Label / X and numeric columns, or table columns in any order. Column letters and ranges such as B, D:F refer to the file. Select the starting data row and bounded row count before using the selection. Hierarchy charts can combine up to six category columns into paths. Scatter and bubble charts validate and normalize numeric X coordinates with the selected source punctuation.", mobile: "Import mapping can inspect up to one thousand data rows plus headings and one hundred columns from files under 500 KB. Choose number punctuation and optional blank-as-zero handling for charts. Imports replace only the draft; tables keep overall colours and typography while resetting cell overrides, merges and manual grid sizes. Cancelling keeps the previous draft.", panel: "data" },
  { id: "mockup-photo-fit", title: "Fit photos and style mockup captions", category: "canvas", web: "Device and print mockups offer Fill screen and Fit photo. Fill crops a copied photo to the screen; Fit keeps its current crop and places it over an editable screen background. Set page-relative size and group rotation, choose the screen background colour and a catalogue or saved brand font for browser and instant-photo captions.", mobile: "The optional preview uses the same fitting and font choices as insertion. Fit photo keeps photo effects, flips, opacity and links in the grouped mockup while leaving the source photo in place. Ungroup to edit the screen background and picture separately. Saved frame palettes set material, details and screen colours; current colours can be saved to Brand styles.", panel: "grid" },
  { id: "mockup-frames", title: "Create editable device and print mockups", category: "canvas", web: "Open Photo layouts and Device and print mockups. Choose phone, tablet, laptop, browser window, poster frame or instant photo. Set frame colours and an optional browser address or photo caption. Insert an empty screen or fill it with a copy of one selected unlocked photo.", mobile: "Mockups use grouped shapes and a normal photo frame for the current page duration. Photo copies retain effects, flips, opacity and focal placement while cropping to the screen; the original stays in place. Select the screen to replace its source, or ungroup to edit frame details. Extreme photo aspect ratios may require a different mockup.", panel: "grid" },
  { id: "clipboard-proportions", title: "Paste vector artwork across different page shapes", category: "layers", web: "Copied text and vector selections retain source-page dimensions. Pasting into a differently shaped page fits the source canvas proportionally inside the destination, keeping artwork proportions and relative placement. Groups, styling and supported motion paths remain editable.", mobile: "The same fitting is used by normal layer paste and proportion-preserving saved-element insertion. Existing photo and video clipboard ownership rules remain in place. Older clipboard entries without source dimensions keep relative placement.", panel: "layout" },
  { id: "saved-element-proportions", title: "Reuse artwork across different page shapes", category: "layers", web: "Saved elements can Keep source proportions when inserting into a different page size. The source page fits proportionally inside the destination, retaining the selection’s relative placement, groups and timing. Text, shapes, borders and paragraph spacing scale together.", mobile: "Turn the option off for the destination page’s relative layout. Source dimensions travel with newly saved elements and exported element files; older elements without dimensions retain their existing relative behaviour. Insertion still uses normal document undo and size limits.", panel: "elements" },
  { id: "match-selected-sizes", title: "Match the sizes of selected layers and groups", category: "layers", web: "Layout includes Match selected sizes. Match widths, match heights or proportionally fit each selected layer or group inside a reference box. Choose the first selection, the largest selection or the smallest selection as the reference.", mobile: "Each independent layer or group scales about its own centre; groups stay intact and proportions are retained. Rotated bounding boxes define the measured size. Largest and smallest compare the requested axis, or box area when fitting both dimensions. Text, stroke and paragraph styling scale with their artwork, subject to normal size limits.", panel: "layout" },
  { id: "selected-vector-svg", title: "Download selected vector artwork as SVG", category: "layers", web: "Style selected vectors includes an SVG download for ordinary shapes, drawings, symbols and connectors. It retains current keyframe placement, rotation, flips, colours, gradients, opacity, stroke patterns, connector caps and supported colour blends in a document fitted around the layer bounds or preserving the page dimensions. Optional extra padding and page-colour background control the output.", mobile: "Download up to one hundred selected vector layers. Group members are included when they are eligible vectors on the current page. Text, media, empty photo frames and data graphics are outside this vector-only export. Timeline entry and exit animations are not baked into the static SVG; use normal visual exports for those effects.", panel: "layout" },
  { id: "drawing-shape-conversion", title: "Tidy a drawing into an editable shape", category: "layers", web: "Select a freehand drawing and open Tidy drawing into a shape. Choose rectangle, ellipse, triangle, diamond, star or hexagon. Rough closed rectangles and ellipses can show a suggested shape, which you choose explicitly.", mobile: "Conversion uses the drawing’s current box and retains placement, rotation, outline, effects, group, animation and timing. Open paths become outline shapes. The result remains editable with normal shape controls; document Undo restores the original drawing.", panel: "layout" },
  { id: "paragraph-spacing", title: "Set space between text paragraphs", category: "layers", web: "Format selected text includes exact paragraph spacing from zero to three hundred units relative to a 1080-pixel page height. Extra spacing follows explicit line breaks; automatically wrapped lines keep normal line spacing. It also separates list items without changing their continuation-line spacing.", mobile: "Paragraph spacing participates in text fitting, curved text, backgrounds, text effects, underlines and strikethroughs in the shared layout. Copied styles and resized text retain the setting. Zero preserves existing layouts, and document Undo restores previous spacing.", panel: "layout" },
  { id: "balanced-headings", title: "Balance wrapped heading lines", category: "layers", web: "Select text and enable Balance heading lines in Format selected text. Enabling it turns wrapping on. Short normal paragraphs keep their existing line count while choosing more even word breaks. The source text is unchanged, and explicit paragraph breaks remain separate.", mobile: "Balanced layout is shared by canvas previews and exports, works with text fitting and text direction, and is kept in copied styles and reusable elements. Lists and long paragraphs retain normal wrapping. Paragraphs up to six lines, eighty words and six hundred characters use the bounded balancing layout.", panel: "layout" },
  { id: "graphic-style-transfer", title: "Reuse chart and table styling without replacing content", category: "data", web: "Copy and paste styles between graphic layers to transfer palettes, text formatting and supported appearance settings. Titles, captions, descriptions, reference targets, numeric bounds and bubble column assignments stay with the destination chart.", mobile: "Table style transfer retains destination rows, cell formatting, merges and manual dimensions. If a pictogram style conflicts with the destination filled count, its original mode and total are retained while compatible styling is applied. Invalid stored graphic styles are skipped.", panel: "data" },
  { id: "text-direction", title: "Set left-to-right or right-to-left text flow", category: "layers", web: "Select text and open Format selected text. Text direction can be Auto, Left to right or Right to left. Auto uses the first strong letter. Direction affects straight-paragraph shaping and mixed-language punctuation, while physical left/centre/right alignment stays separate.", mobile: "Text direction applies to one or many unlocked text layers, is retained by style copy/paste and saved projects, and is shared by native and export drawing. Right-aligned RTL lists hang continuation lines from the right edge. Curved text retains its existing glyph arrangement.", panel: "layout" },
  { id: "pictogram-symbols", title: "Use library icons in pictograms", category: "data", web: "In Pictogram symbols, choose Library icon. Search the vector-symbol catalogue by name, category or tags, then pick an icon. Symbols can represent category shares or filled-versus-remaining counts, using the chart palette and spacing.", mobile: "The icon picker shows eight choices per page. Pictogram icons use editable vector strokes and curves in shared native, web and SVG rendering, and portable chart styles retain the chosen library icon. A completed-checklist starter demonstrates the mode.", panel: "data" },
  { id: "chart-label-wrap", title: "Wrap long category labels", category: "data", web: "For category charts and histograms, enable Wrap category labels in Text size and plot style. Vertical charts reserve space for up to three label lines. Horizontal bar labels use up to two lines and adapt text size to their row height. Excess text ends with an ellipsis.", mobile: "Wrapping works with single or multiple series and shared web/native/SVG output. Source labels are kept unchanged, and portable chart styles retain the wrap setting. Increase graphic size or reduce chart text size when labels remain too dense.", panel: "data" },
  { id: "chart-x-format", title: "Format horizontal values independently", category: "data", web: "For Scatter and Bubble, open Axes and scale, then Horizontal axis number format. Choose a numeric, percentage or currency format, locale, decimals and units independently of Y values. Apply the horizontal format to the draft. Source X coordinates stay numeric and unchanged.", mobile: "In Text size and plot style, choose Point value labels: Y value or X and Y coordinates. Coordinate labels use the horizontal and vertical number formats; bubble labels also show the size. Portable styles include the X format when number formats are enabled, plus the point-label mode.", panel: "data" },
  { id: "table-row-cleanup", title: "Remove empty and duplicate table rows", category: "data", web: "Open Remove empty or duplicate rows in the Data tab. Empty-row cleanup checks the whole row. Duplicate cleanup compares all columns or one selected column, optionally ignoring case or surrounding whitespace. The first matching row and any header remain; original text is not rewritten.", mobile: "Remaining rows keep their cell styles, horizontal merges and row sizes. Unmerge cells spanning multiple rows before cleanup. Undo row cleanup restores both data and formatting while the draft still matches the cleanup result. A table always keeps at least one row.", panel: "data" },
  { id: "data-range-actions", title: "Fill, clear and clean source cells", category: "data", web: "Open Fill, clear and clean a range in Data or the expanded editor. Enter a cell or rectangular range, or leave blank for all cells. Fill repeats a value; Clear empties cells. Convert formatted numbers removes supported currency marks, grouping separators and accounting notation using your chosen punctuation format.", mobile: "Number cleanup keeps percentage points: 25% becomes 25. Unrecognized text stays unchanged. Actions edit source cells while table formatting stays attached to positions. Undo data action and Redo data action restore the latest action while the source still matches it. Update or insert the graphic to apply the draft.", panel: "data" },
  { id: "expanded-data", title: "Edit data in a larger workspace", category: "data", web: "Choose Expand data editor in the Data tab. A larger dialog shows twenty rows per page and supports the same cell editing, keyboard movement, spreadsheet paste and table structure actions as the panel. Switch to Source data for CSV/TSV correction.", mobile: "The expanded editor opens as a sheet with a keyboard-aware scrolling grid and twenty-row pages. It edits the same draft as the panel. Done editing data closes the sheet; update or insert the graphic afterwards to apply draft changes to the canvas. Project or selection changes close it automatically.", panel: "data" },
  { id: "bubble-columns", title: "Choose bubble-chart Y and size columns", category: "data", web: "Enable multiple series, then choose Y values from and Bubble sizes from in Data. X coordinates stay in the first column. Choose Equal sizes to use unit weights. Only the selected Y values determine the vertical scale and target shortcuts.", mobile: "Bubble roles stay attached to data when columns are reordered. If a selected Y column is removed, the first remaining column is used; removing the selected size column switches to equal sizes. Other series stay in the source and CSV. Turning multiple series off resets column roles.", panel: "data" },
  { id: "hierarchy-import", title: "Paste category columns into hierarchy charts", category: "data", web: "Choose Treemap or Packed circles and open Paste category columns. Paste CSV or spreadsheet cells with one to six category columns and a final numeric size column. Skip the first row if it contains headings. Up to fifty rows become editable slash-separated paths.", mobile: "Category import checks nonnegative sizes, unique paths and conflicting group/leaf names before replacing the draft. Category cells must be nonempty and cannot contain /. The resulting path/value data stays editable in cells and source, and the canvas changes when the graphic is updated.", panel: "data" },
  { id: "packed-circles", title: "Show nested groups with packed circles", category: "data", web: "Choose Packed circles and use the same slash-separated leaf paths as treemaps. Positive leaf values determine circle areas; zero values are hidden. Nested outlines show parent groups and include packing space. Group circles do not represent exact proportional areas because they contain gaps.", mobile: "Packed circles support up to six path levels, per-leaf colours, label and value toggles, fonts, number formats, captions, spacing and SVG output. The layout is cached while only styling changes. A starter provides grouped regions, and raw paths and values remain editable and exportable.", panel: "data" },
  { id: "filled-pictograms", title: "Create filled-versus-remaining pictograms", category: "data", web: "In Pictogram symbols, choose Filled and remaining. The first source value becomes the whole number of filled icons; Total symbols sets the overall count. In Data, the Filled items slider edits that first value. Choose a shape and filled/remaining colours to show messages such as seven out of ten.", mobile: "Filled-item pictograms keep both completed and remaining icons visible. The legend can show the count, percentage or both. Lowering the icon total below the filled count requires correcting the source before applying. Category shares remains available as a separate mode.", panel: "data" },
  { id: "progress-charts", title: "Display goal completion with progress charts", category: "data", web: "Choose Progress bar, Progress ring, Radial progress or Progress dial. The first source value is a percentage from 0 to 100, and the first label names the goal. The Progress percentage slider edits that value while retaining the rest of your data. Choose filled and remaining colours, thickness and rounded endpoints.", mobile: "Progress charts have percentage labels, editable goal text, saved palettes, fonts, titles, source captions and SVG output. Percentage formatting supports decimals, locale and prefixes or suffixes. Thin rings, bold radial bands, bars and semicircular dials share the same data controls and rendering.", panel: "data" },
  { id: "graphic-captions", title: "Add context to charts and tables", category: "data", web: "In the Design tab, open Title, caption and SVG description. The title and source caption reserve space inside the graphic above and below its content. Both use the selected graphic font and appear in raster, PDF, presentation and vector output.", mobile: "Alternative text is embedded as a description in SVG export. Describe the main finding and relevant values. If it is blank, SVG includes a short summary of chart categories or table dimensions. Descriptions do not create accessibility metadata in raster, PDF or presentation exports; visible title and caption text still render.", panel: "data" },
  { id: "table-starters", title: "Build tables from common layouts", category: "data", web: "Choose Table and open Start from sample data. Eight starters cover agendas, comparisons, checklists, standings, timetables, budgets, packages and a blank monthly planner. Each lists its row and column count. Sample colours are optional; source values remain editable.", mobile: "Choosing a table starter replaces the draft until you update or insert the graphic. Existing table colours are kept by default, including body, header, stripe and grid colours. Example budget amounts and totals are static values; edit or regenerate summary rows when data changes.", panel: "data" },
  { id: "diagram-starters", title: "Build editable diagrams from starters", category: "canvas", web: "Open Connectors and expand Editable diagram starters. Choose a four-step process, decision flow, organisation chart or mind map. Enter one node label per line, choose horizontal or vertical layout, set node/text/line colours and insert. Blank labels use the starter text.", mobile: "Diagram starters insert ordinary text, shape and connector layers for the current page duration. Each node and its text share a group. Connectors remain independent, so reposition lines after moving nodes. Diagrams can be edited, duplicated, exported or stored in the reusable element library.", panel: "connectors" },
  { id: "chart-starters", title: "Start with correctly structured chart data", category: "data", web: "Open Start from sample data in the Data tab. Search twenty examples covering comparisons, shares, distributions, relationships, hierarchy and animated rankings. Choosing one replaces draft data and formatting; sample colours are optional. Update or insert the graphic to apply it to the canvas.", mobile: "Chart starters include source-row and numeric-column counts, searchable descriptions and illustrated chart types. Existing palette and text colour are kept unless sample colours are enabled. Starter formatting clears settings from the previous draft so unrelated targets and axes do not carry over.", panel: "data" },
  { id: "chart-race", title: "Animate changing rankings", category: "data", web: "Choose Bar chart race and use multiple-series data with two to six frame columns. Rows are categories; column names are frame captions. Nonnegative values interpolate across the graphic timeline duration, while category colours stay fixed. All frames use a shared maximum scale.", mobile: "Set visible rankings and bar spacing, then play the timeline. Still-image / SVG frame controls vector output and draft previews. Turn animation off to freeze that frame on the timeline. Source CSV retains every category and frame, including those below the displayed ranking limit.", panel: "data" },
  { id: "pictogram-chart", title: "Show shares with repeated symbols", category: "data", web: "Choose Pictogram to represent positive category shares using 10 to 100 whole symbols. Choose circle, square, diamond, star or person, set the column count and spacing, then style each category. A largest-remainder allocation fills the chosen icon total; small shares can round to zero icons.", mobile: "The legend retains original values and can show percentages or both. First-series data supplies shares; other series stay in the source. Configure fonts, palette, legend position, symbols and spacing. Portable chart styles retain symbol settings, and native, web and SVG output use the same drawing.", panel: "data" },
  { id: "chart-type-picker", title: "Find the right chart type", category: "data", web: "Open the chart type card in Charts and tables to browse illustrated choices. Search by chart name or purpose, or filter comparison, trends, parts of a whole, relationships, distribution and hierarchy. Changing type keeps draft source data until the graphic is updated.", mobile: "The chart picker uses illustrated two-column cards with group filters and search. Dot plots compare values across categories without bars or connecting stems; multiple series share category positions and retain series colours and legends. Point size, numeric scales, targets and value formatting stay editable.", panel: "data" },
  { id: "treemap-chart", title: "Create a grouped treemap", category: "data", web: "Choose Treemap and enter unique leaf paths separated by /, up to six levels. Positive values determine tile area inside their groups; zero values are hidden. Group headings reserve space above children. Choose individual leaf colours, font, number format and tile spacing. A path cannot be both a group and a leaf.", mobile: "Treemaps retain editable paths and values in the data grid and CSV. Start with the explicit example, adjust group paths and values, then update the graphic. The first series is displayed while extra series remain in source data. Nested groups, value labels and spacing use shared native, web and SVG drawing.", panel: "data" },
  { id: "bubble-chart", title: "Compare three values with bubble charts", category: "data", web: "Choose Bubble. Numeric row labels provide X coordinates; the first data series provides Y positions and the second provides nonnegative sizes. Bubble area follows size, with large bubbles painted first and zero sizes hidden. Missing size series produces equal bubbles. An example replaces draft data explicitly.", mobile: "Bubble charts support per-point colours, X and Y range expansion, reference targets, fonts, size scaling, outline weight and fill opacity. Value labels show Y / size. Extra source series remain editable and exportable. Sorting keeps sizes and category colours with their points. Rendering is shared with SVG output.", panel: "data" },
  { id: "histogram-chart", title: "Plot a distribution with histogram bins", category: "data", web: "Choose Histogram in Charts and tables. Values in the first data series become equal-width bins. Paste raw observations to replace the draft with up to 50 numbers. Maximum histogram bins sets the detail; equal values use one bin. Number formatting applies to boundaries, while frequencies remain counts.", mobile: "Histogram charts retain the original observations in the data grid and source CSV. Export histogram bin counts copies or downloads the calculated ranges and frequencies separately. Adjust axes, font, plot colour, bin count and bar spacing, then update the graphic. The maximum observation is included in the final bin.", panel: "data" },
  { id: "funnel-chart", title: "Build an editable funnel chart", category: "data", web: "Choose Funnel in Charts and tables. Stage labels and nonnegative values follow data-row order, and widths use a shared maximum. Category colours style each stage. Text size and Stage spacing control readability. Multiple-series data is retained while the first series is displayed.", mobile: "Funnel charts support editable stages, formatted values, font selection, individual colours and spacing. Use row-order controls to arrange stages. Funnels preview and export through the same renderer, including SVG output.", panel: "data" },

  { id: "graphic-fonts", title: "Match chart and table fonts to the design", category: "data", web: "Graphic font in Design chooses one catalogue font for chart labels, legends, axes, targets or table cells. Saved brand fonts appear as shortcuts. Replace a font throughout this design includes chart and table fonts, and Brand styles can apply a saved body font to data graphics.", mobile: "Graphic font has a searchable, paged catalogue and saved brand-font shortcuts. Preview and export wait for the selected font. Portable chart/table styles carry the family, and SVG keeps the chosen font name for devices where it is available.", panel: "data" },

  { id: "chart-type-size", title: "Adjust chart text for reading distance", category: "data", web: "Chart Design includes Chart text size from 50% to 300%. It scales legends, labels, axis titles, values and target captions together, while keeping the outer graphic size. Default text size restores automatic sizing, and chart-style files carry the chosen scale.", mobile: "Use Chart text size in Design to enlarge or reduce chart typography. Legends and plot spacing adapt to the chosen size. Data and graphic bounds stay unchanged, and the same sizing is used by exports.", panel: "data" },

  { id: "present-countdown", title: "Run a presentation countdown", category: "pages", web: "Switch the presentation clock from Elapsed to Countdown. Choose a preset or set 0.5–120 minutes, then start or resume it. Reset pauses and restores its configured duration. The clock displays Time is up at zero, without moving the page.", mobile: "Presentation clock controls include an independent countdown with presets and custom minutes. Background activity and switching to elapsed mode pause its countdown; returning resumes a running timer. The stopwatch keeps its separate elapsed time." },
  { id: "present-upcoming", title: "Preview the upcoming page while reading notes", category: "pages", web: "In presenter notes, expand Up next to view the next visible page without navigating. Preview follows hidden-page filtering and the loop setting, and pauses while the app is in the background.", mobile: "Scroll presenter notes to Up next and expand it for a small page preview. This does not change the current slide. Use Next to advance when ready; the upcoming page follows the visible presentation order." },

  { id: "contact-links", title: "Create structured contact links", category: "layers", web: "The Link panel can build email links with subjects/messages, phone links, or SMS recipient/message links. Selecting a grouped layer applies the destination across its active group members. Use the details in the draft, then Apply link. Copy destination copies the normalized target. Mixed links are identified when selected artwork has different destinations.", mobile: "Open Link for selected artwork or a group. In Position and groups, Links for selected artwork can apply a destination to several chosen layers together. Build email, phone or SMS details, then apply to the selection. Contact links open through the viewer or device’s supported app. Copy destination also supports page links.", panel: "link" },

  { id: "saved-palettes", title: "Reuse saved palettes in gradients and charts", category: "data", web: "Saved palettes appear in Fills and backgrounds and chart Design. Applying a palette loads the draft, while Save palette records the current colours in Brand styles. Gradient files preserve stop geometry and opacity; palettes carry colours only.", mobile: "Use Saved palettes in gradient or chart controls to reuse Brand styles. Gradients use up to eight evenly sampled colours from larger palettes. Saving chart colours stores up to the first ten distinct colours. Repeated grids can optionally group every copied tile.", panel: "fill" },

  { id: "typography-layouts", title: "Preview and reuse typography layouts", category: "layers", web: "Choose a text combination, enter its heading, supporting text and eyebrow, then expand Preview selected combination. Quotation and lower-third presets create editable grouped text and accents. Use a saved font pairing can override the layout fonts from Brand styles. Insert selected combination adds it to the page.", mobile: "Text combinations include quotation and lower-third layouts, optional previews and saved heading/body font pairings. Preview uses the page colour without other artwork. Insert creates ordinary grouped layers that can be edited, moved or saved as a reusable element.", panel: "compositions" },

  { id: "notes-scroll", title: "Auto-scroll presenter notes", category: "pages", web: "Open presenter notes and start Auto-scroll notes. Choose a reading speed from 12 to 60 pixels per second. Wheel, touch or pointer interaction with the notes pauses scrolling. Starting again at the end returns to the top; changing pages stops it.", mobile: "Presenter notes include adjustable auto-scroll. Dragging notes pauses scrolling, and background activity suspends it. The toolbar scrolls horizontally so controls leave room for the notes. Text size remains adjustable separately." },

  { id: "table-find", title: "Find and replace table text", category: "data", web: "Open Find and replace table text in the graphic Data tab. Enter literal text, an optional replacement and a cell range, or leave the range blank for all cells. Review the match count, then replace. Cell formats stay in place; update the graphic to apply the draft.", mobile: "In chart and table Data controls, open table find-and-replace. Match case and Match entire cell narrow the search. An empty replacement removes matches. Whitespace trimming and case conversion use the same range. Cells stay within their 200-character limit.", panel: "data" },
  { id: "presentation-blank", title: "Blank the presentation screen", category: "pages", web: "Use Blackout or press B to cover the slide in black. White screen or W covers it in white. Press the same shortcut again to restore the slide. Automatic advancement pauses while the cover is active, and changing pages clears it.", mobile: "Use Blackout or White screen in the presentation controls. The cover hides slide artwork and links, pauses automatic advancement and clears when changing pages. It does not change the design." },

  { id: "chart-target", title: "Mark chart targets and benchmarks", category: "data", web: "In chart Design, open Target or benchmark line, enter a value, label and colour, then apply. Average, median, minimum and maximum shortcuts fill a fixed target from current source values. Apply the target and recalculate after data changes. The value axis expands to keep the target visible. Percentage-stacked charts use a target between -100 and 100 percentage points. Reference values stay in the destination when importing chart styles.", mobile: "Open Target or benchmark line to annotate bar, column, line, area, lollipop or scatter charts. The dashed line and caption appear in canvas and graphic exports. Remove target clears the annotation.", panel: "data" },

  { id: "table-numbers", title: "Format numeric table cells and calculate summaries", category: "data", web: "Choose a cell range in Cell appearance. Selected cell typography changes relative text size and vertical alignment. Cell number format applies currency, percent, locale, decimals or unit text. Values stay unchanged in the data grid and CSV. Add a summary row calculates numeric cells in each selected column; summaries contain fixed numbers. Fit row heights to content shares the table height based on wrapped text.", mobile: "Select a range in Cell appearance to apply number formats or open Selected cell typography for text size and vertical alignment. Unit prefixes and suffixes change display only. Summary rows append totals, averages, minima, maxima or numeric counts. Recalculate summaries after changing values. Enable row fitting to size rows from their content.", panel: "data" },
  { id: "pie-appearance", title: "Control pie and donut slice appearance", category: "data", web: "In chart Design, choose source values, percentages or both for legend values, then enable Show values. Rotation changes the first slice position; slice spacing adds gaps while keeping small slices visible. Percentages use positive slices only.", mobile: "Pie and donut settings include legend value format, rotation and spacing. The donut centre total retains its number format while slice percentages describe shares of the positive total.", panel: "data" },

  { id: "repeat-spacing", title: "Create staggered patterns and fit repeated artwork", category: "layers", web: "Repeat selection supports regular grids or alternate rows and columns shifted by half a cell. Fit gaps within page margins calculates spacing from the artwork's current position; create the grid to apply it.", mobile: "Choose rows, columns and stagger direction in Repeat selection. In Position and groups, choose several layers and open Repeat selected artwork as one tile to repeat them together. Fit gaps calculates spacing while keeping matching opposite margins. Move or shrink the original if the selected cells cannot fit.", panel: "repeat" },
  { id: "scatter-lines", title: "Connect scatter points and share X ranges", category: "data", web: "Scatter charts use numeric X coordinates in the first column. Sort by Numeric X coordinate in Data, then enable Connect scatter points in Design. Connections follow row order. Horizontal scale bounds expand the range without hiding points.", mobile: "Use Numeric X coordinate sorting to arrange scatter rows, and enable connections in chart geometry. Straight, stepped and smooth lines are available. Use horizontal X bounds to coordinate several charts.", panel: "data" },
  { id: "gradient-files", title: "Reuse gradients across designs and devices", category: "layers", web: "Download a gradient as SVG at the current page size. Transfer gradient styles exports and imports editable settings, including stop positions, opacity and radial focus. Imported styles load the draft; apply the fill or background separately.", mobile: "Use Download gradient as SVG for vector artwork. Export a gradient-style file to transfer its settings between devices; import and apply it from Fills and backgrounds.", panel: "fill" },
  { id: "document-quality", title: "Choose PDF and presentation image detail", category: "pages", web: "Smaller-file, balanced and high-detail profiles control page-image resolution and JPEG quality in PDF and presentation exports. These documents contain rendered page images; SVG graphic exports retain vector paths and editable labels.", mobile: "Choose a document quality profile in PDF or presentation export. High detail captures up to 4,096 pixels on the long edge; smaller-file and balanced profiles reduce image sizes." },

  { id: "tool-search", title: "Find an editing tool", category: "canvas", shortcut: "/", web: "Press / outside text fields to search tools by name or task.", mobile: "Open tool search and enter the editing action you need." },
  { id: "fit", title: "Fit the page and focus a selection", category: "canvas", shortcut: "Shift + 1 / Shift + 2", web: "Fit the full page with Shift + 1, or focus selected artwork with Shift + 2. Ctrl/Cmd + mouse wheel zooms around the pointer.", mobile: "Use Fit page or Focus selection. Turn on canvas navigation to pan and pinch the view. Double-tap in navigation mode to fit the page." },
  { id: "select", title: "Select several layers", category: "layers", shortcut: "Shift + click", web: "Shift-click to add or remove layers, or drag across empty canvas space to select a region. Ctrl/Cmd + A selects editable foreground layers on the page.", mobile: "Open Position and groups to select several layers. The selected members can be aligned, transformed, named, copied, or saved together.", panel: "layout" },
  { id: "overlap", title: "Reach overlapping artwork", category: "layers", shortcut: "Ctrl/Cmd + click", web: "Ctrl/Cmd-click repeatedly to cycle overlapping layers. Open the Layers here picker to search and choose one directly.", mobile: "Open Layers here to choose from overlapping artwork. Hidden and locked layers are excluded from the picker." },
  { id: "edit", title: "Edit text or crop a photo", category: "canvas", web: "Double-click text to edit it in place. Double-click a photo or video to adjust its crop.", mobile: "Double-tap text to open its editor, or double-tap a photo or video to open crop controls." },
  { id: "nudge", title: "Position artwork precisely", category: "layers", shortcut: "Arrow keys / Shift + arrows", web: "With the canvas focused, arrows move selected artwork by one pixel; Shift moves it by ten. Position controls also accept exact sizes and coordinates.", mobile: "Use Position and groups for exact width, height, left, and top values, or drag, pinch, and rotate selected artwork on the canvas.", panel: "layout" },
  { id: "group", title: "Keep artwork together", category: "layers", shortcut: "Ctrl/Cmd + G / Shift + Ctrl/Cmd + G", web: "Group selected layers to move and transform them together. Add Shift to ungroup.", mobile: "Select layers in Position and groups, then choose Group. Choose Ungroup when the members need independent placement.", panel: "layout" },
  { id: "copy", title: "Copy, cut, paste, and duplicate", category: "layers", shortcut: "Ctrl/Cmd + C / X / V / D", web: "Canvas copy and paste use page-relative placement and timing. Cut affects the current page. Duplicate creates another copy of the selected artwork.", mobile: "Use Copy layers, Cut layers, and Paste layers. Text and shapes can move between designs; photos and video paste within their original design." },
  { id: "undo", title: "Undo a design edit", category: "layers", shortcut: "Ctrl/Cmd + Z / Shift + Ctrl/Cmd + Z", web: "Undo and redo document changes with the toolbar or these shortcuts. The text editor has local undo controls while a text draft is open.", mobile: "Use the editor undo and redo controls. Text drafts and saved-element library changes have their own undo controls." },
  { id: "library", title: "Reuse custom elements", category: "layers", web: "Save text and vector selections under Insert → Saved elements. Search, preview, rename, replace, or transfer them using element files.", mobile: "Open Insert → Saved elements, or save a multi-layer selection from Position and groups. Element files transfer saved artwork between devices.", panel: "elements" },
  { id: "palette", title: "Reuse colours from a page", category: "canvas", web: "Document colours can sample a palette from the current page, including photos. Select a document colour, then an extracted swatch to replace it.", mobile: "Document colours can extract the current page palette, apply it to the design, or save it as named brand styles.", panel: "colours" },
  { id: "guides", title: "Place guides and margins", category: "canvas", web: "Use Guides and margins to add exact guides or a layout grid. Drag guides from the rulers when guide editing is enabled.", mobile: "Use Guides and margins for exact positions, grid columns, gutters, and physical ruler units. Turn on guide editing to move guides on the canvas.", panel: "guides" },
  { id: "cells", title: "Paste spreadsheet cells", category: "data", shortcut: "Tab / Enter", web: "Paste a rectangular range directly into a chart or table grid. Tab moves across cells and Enter moves down; the grid can add a new row at its end.", mobile: "Use the data-paste panel for rectangular spreadsheet ranges. The keyboard Next action moves across cells and can add a new row.", panel: "data" },
  { id: "table", title: "Format a table range", category: "data", web: "Focus a cell to target its formatting, or enter a range such as A1:C3. Copy cell styles to repeat a formatting pattern while keeping the target text.", mobile: "Focus a cell, then use Cell appearance. Select a row, column, or all cells, and copy or paste cell styles without changing data.", panel: "data" },
  { id: "chart-design", title: "Style a chart without changing its data", category: "data", web: "Use Data to edit values and series, then Design for chart styles, scales, legends, axis titles, custom units, and donut-centre text. Open Preview graphic to inspect the draft before applying it.", mobile: "Switch between Data and Design above the graphic controls. Preview graphic shows a draft; the pinned apply action saves your changes. Reset draft restores the saved graphic or default data.", panel: "data" },
  { id: "table-fit", title: "Fit table columns and text", category: "data", web: "In Design, turn on Fit columns to content to measure cell text, or Shrink text to fit cells for crowded content. Manual column sizing turns automatic widths off.", mobile: "In the table Design tab, use Fit columns to content and Shrink text to fit cells. The table keeps its outer size; manual widths take over when adjusted.", panel: "data" },
  { id: "table-scale", title: "Colour numeric table cells", category: "data", web: "Choose a cell range, then open Cell colour scale. Apply a palette with an optional zero centre and readable text colours. Reapply the scale after editing values.", mobile: "Choose a range in Cell appearance, then open Cell colour scale. Numeric cells receive colours; blank, text and merged cells keep their styles.", panel: "data" },
  { id: "bulk-create", title: "Generate pages from spreadsheet records", category: "data", web: "Bulk create connects spreadsheet columns to text, QR codes, page names, notes, sections, and layer links. Filter a row range by matching or blank values before generating pages.", mobile: "Use Bulk create to connect a CSV or pasted spreadsheet to the template page. Page fields and links can generate pages without connected text. Preview records and choose a row range or filter.", panel: "bulk" },
  { id: "selection-shadow", title: "Give selected artwork consistent shadows", category: "layers", web: "Select foreground text, shapes, photos or videos and open Shadows for selection. Apply a preset, set exact colour and measurements, or remove shadows in one edit.", mobile: "In Position and groups, open Shadows for selection to style mixed artwork together. Unlock selected layers before applying a shadow.", panel: "layout" },
  { id: "selection-filter", title: "Apply a photo look to several layers", category: "layers", web: "Style selected photos and videos includes colour filters and strength. Apply once to replace existing colour and blur adjustments; frames, crops, borders and timing stay in place.", mobile: "In Position and groups, open Style selected photos and videos. Choose a filter and strength, then apply to all matching selected media in one edit.", panel: "layout" },
  { id: "drawing-points", title: "Refine a freehand drawing", category: "layers", web: "Select a drawn path and open Drawing points in its layer controls. Simplify small deviations, reverse stroke direction, or straighten an open path between its endpoints. Undo restores its original points.", mobile: "Select a drawing, open its shape controls, then Drawing points. Precision controls how much detail simplification retains. Closed drawings keep at least three points." },
  { id: "export-order", title: "Export pages in a different order", category: "pages", web: "Choose pages in the export dialog and enter the desired sequence, such as 3,1-2. Descending ranges such as 5-1 reverse a range. Each repeated page number is included once.", mobile: "Choose pages in the export sheet and enter their output order. This sequence is retained for images, PDFs, presentations and presenter-note files." },
  { id: "page-range", title: "Manage many pages", category: "pages", web: "Page ranges such as 2, 4-6 can replace, add to, or remove from the page-manager selection. Duplicate, reorder, name, or hide the selected pages together.", mobile: "Enter a page range in Manage pages to select a batch, then duplicate, move, name, or hide those pages.", panel: "pages" },
  { id: "page-transfer", title: "Move artwork between pages", category: "pages", web: "Select foreground layers and use Move or copy selected layers to pages. Copy to several pages or move to one destination in one undoable edit.", mobile: "Manage pages and Position and groups include artwork transfer controls. Destination pages must fit the selection's relative timing.", panel: "pages" },
  { id: "present", title: "Present a document", category: "pages", web: "Use Present for page navigation, notes, timed playback, a page picker, and temporary pen or laser marks. Hidden presentation pages are skipped.", mobile: "Use Present to show page captures with notes, a page picker, timed playback, and temporary pen or laser marks. The design artwork is preserved." },
  { id: "bulk-photos", title: "Use different photos in bulk-created pages", category: "data", web: "Name source photo layers, then connect a template photo or empty photo frame to a spreadsheet column containing those names. Names match without letter-case differences; different photos need unique names. Blank cells keep the template photo.", mobile: "Bulk create can replace photos and photo frames from named image layers already in the design. Referenced source and template images must be available on the device. Placement and style follow the template; row-specific errors identify missing or ambiguous names.", panel: "bulk" },
  { id: "graphic-files", title: "Transfer graphic styles and export editable vectors", category: "data", web: "Data graphics download as SVG with editable labels. Transfer chart or table appearance through style files in Design, optionally including number formats or table header settings. Use this data as a chart/table converts compatible drafts without dropping rows.", mobile: "Charts and tables export as SVG through the current canvas and save through the device controls. Style files move appearance between devices. Data, merges, titles and destination structure stay separate from transferred appearance.", panel: "data" },
  { id: "rehearsal", title: "Rehearse slide durations", category: "pages", web: "In Present, open Rehearse timings and start recording page time. Pause to review accumulated visits, then apply timings and close. Unvisited pages keep their durations; the document must stay unchanged during rehearsal.", mobile: "Use Rehearse timings in Present. Time pauses in the background, while loading a page, and in the page picker. Pause before applying the captured durations in one document edit." },
  { id: "text-replacement-preview", title: "Preview text replacements and change one occurrence", category: "layers", web: "Find and replace results show the number of occurrences in each text layer. Preview replacement shows the resulting text before applying. Replace first occurrence changes only the first match in that layer; Replace in layer changes every match there, while Replace all follows the active design, page or selection scope.", mobile: "Replacement previews retain literal dollar signs and backslashes and use the same case and whole-word settings as the replacement. Locked layers remain unchanged. Large replacement expansions are rejected before committing any changes, with a maximum of one hundred thousand characters per text layer.", panel: "search" },
  { id: "svg-path-import", title: "Import editable SVG geometry", category: "layers", web: "Open Import editable SVG geometry in Symbols. Choose an SVG file smaller than 32 KB, paste SVG markup with paths, rectangles, circles, ellipses, lines or polygons, or paste path d data. Original paints and viewport margins are not imported; choose the colour and appearance here. Paste path d data beginning with M. Multiple outlined subpaths are inserted as grouped layers, retaining their relative positions. Absolute and relative move, line, cubic, quadratic, smooth, arc and close commands are accepted. Choose curve sampling detail, colour, line weight or filled closed geometry before inserting. Separate SVG elements with one closed path each can be filled together.", mobile: "The path appears as an editable drawing fitted proportionally to the current page. Curves become sampled drawing points with a bounded point count. Style, transform, group, convert, copy and export it using existing vector tools. Element and group matrix, translate, scale, rotate and skew transforms are applied to editable points. Nested viewports, CSS transforms, definitions, references, images, text, masks, clipping and filled compound holes are unsupported. Geometry is extracted as numbers; original source markup is never executed or displayed. Up to one hundred outlined subpaths share a bounded four-thousand-point budget.", panel: "symbols" },
  { id: "crop-precision", title: "Use a custom crop ratio and exact focal position", category: "layers", web: "In Crop, open Custom ratio and exact focus. Enter width and height proportions, swap orientation, or match the page ratio. Enter horizontal and vertical focus percentages to move the crop window precisely between its available source edges.", mobile: "Custom ratios use the same crop geometry as presets and preserve displayed area and existing scale keyframes. Focus follows visible flips and preserves the crop size. Apply commits the change explicitly, keeping source media and effects available." },
  { id: "photo-look-library", title: "Save and transfer custom photo looks", category: "layers", web: "Open Saved photo looks in the media inspector. Name and save up to twenty combinations of colour, blur, tone, duotone, sharpening and grain adjustments. Search the library, apply a look at a chosen strength, or replace a saved look with the current settings. Position and groups can apply a saved or imported look to up to one hundred selected photos and videos in one edit; saving there uses the first selected layer.", mobile: "The library is scoped to your account on this device. Export a photo-look JSON file and import it in the other editor. Imported looks are shown before applying; save the resulting adjustments to keep the look in the destination library. Applying replaces effects while retaining media, crop, frame, borders, opacity and timing." },
  { id: "photo-detail", title: "Sharpen photos and add film grain", category: "layers", web: "Select an image or video and use Sharpen and Film grain in Adjust. Sharpen increases local edge contrast while respecting transparent edges. Film grain adds a stable monochrome texture. Both controls start at zero and retain the source media.", mobile: "The same detail controls use live sliders in Adjust. Filter matching, copied effects and saved project settings include sharpening and grain. The shared bounded compositor carries these adjustments into preview and export." },
  { id: "qr-calendar", title: "Create calendar-event QR codes and files", category: "data", web: "Choose Calendar event in the QR content builder. Add a title, start and end, location and notes. Timed events use UTC. All-day events include the last date. Use these details to fill the QR draft, or download an iCalendar .ics file.", mobile: "Enter dates as YYYY-MM-DD and UTC times as YYYY-MM-DDTHH:mm. Calendar apps convert UTC events to the recipient’s time zone. The same event can be saved or shared as an .ics file; scanner support for calendar QR payloads varies.", panel: "qr" },
  { id: "qr-content", title: "Create contact, SMS, Wi-Fi, email or phone QR codes", category: "data", web: "Open the QR content builder, choose the destination type, and use those details in the code draft. SMS mode encodes a recipient and optional message. Contact mode creates vCard details that also download as an address-book .vcf file. QR codes download as SVG with their chosen colours and quiet zone.", mobile: "Open QR code and use its content builder for contact, network, email or phone details. Contact mode can save the same details as a .vcf file. Download QR as SVG saves a scalable vector file through the device share or save controls.", panel: "qr" },
  { id: "symbol-svg", title: "Download vector symbols", category: "layers", web: "Choose a library symbol, colour and line weight, then download it as SVG on a transparent background. The file represents the library symbol draft. Search includes science, space and diagram symbols such as laboratory tools, rockets, network nodes and flowcharts.", mobile: "The symbol library includes science, space and diagram artwork and can download the chosen symbol as SVG. Colour and line weight follow the draft controls; the background stays transparent.", panel: "symbols" },
  { id: "keyframe", title: "Animate selected artwork", category: "timeline", shortcut: "K", web: "K adds placement keyframes to one selected visual layer at the playhead and opens its motion controls. Page animation applies entrance or exit styles to layers.", mobile: "Use motion recording and keyframe controls for placement changes, or Animate page for entrance and exit styles.", panel: "animate" },
  { id: "play", title: "Play and split the timeline", category: "timeline", shortcut: "Space / S", web: "Space toggles playback. S splits at the playhead. Outside canvas selection mode, left and right arrows seek by half a second; Shift steps by a frame.", mobile: "Use playback and timeline controls to position the playhead, trim clips, or split at the current time." },
];
export function findEditorGuide(query: string, platform: "web" | "mobile") {
  const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  return EDITOR_GUIDE.filter(entry => words.every(word => `${entry.title} ${entry.category} ${entry[platform]} ${platform === "web" ? entry.shortcut || "" : ""}`.toLowerCase().includes(word)));
}
